```c
#include <stddef.h>

#define MAX_STACK 1024

static char stack[MAX_STACK];
static size_t top = 0;

int is_balanced(const char *s)
{
    top = 0;                     /* reset stack for each call */
    for (const char *p = s; *p; ++p) {
        char c = *p;
        if (c == '(' || c == '[' || c == '{') {
            if (top >= MAX_STACK) return 0;   /* stack overflow → unbalanced */
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;           /* closing without opening */
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{'))
                return 0;                       /* mismatched pair */
        }
        /* ignore any other characters */
    }
    return top == 0;      /* balanced only if every opening was closed */
}
```

**Limit explanation:**  
The function uses a fixed‑size stack of `MAX_STACK` elements; if the input string contains more opening brackets than this limit, the function immediately reports the brackets as unbalanced.

